function makeResultsShareUrl(ranking){const durations=state.games.map((_,i)=>{const raw=state.gameDurations?.[i],value=Number(raw);return Number.isFinite(value)&&value>=0?Math.max(0,Math.floor(value)):null});const payload={v:2,g:state.games.length,p:state.names.length,c:Math.max(1,Number(state.config.courts)||1),t:durations,r:ranking.map(p=>({n:p.name,w:p.w,l:p.l,g:p.g}))};return location.origin+location.pathname+'#results='+encodeResultsBase64(JSON.stringify(payload))}
