function openFinalResultsShare(){const url=makeResultsShareUrl(getRankingRows());openResultsShareSheet(url,'Scan this QR code or copy the link to share the final rankings.',undefined,true)}
async function openLiveLeaderboardShare(){if(!state.sessionCode){status('Generate a rotation first.','err');return}if(window.CRG_PUBLISH_LIVE){const published=await window.CRG_PUBLISH_LIVE();if(!published){status('Live sync is unavailable right now. Share the read-only spectator snapshot instead.','err');return}}const url=location.origin+location.pathname+'?live-leaderboard='+encodeURIComponent(state.sessionCode)+'&view=live-leaderboard';openResultsShareSheet(url,'LIVE leaderboard · updates automatically while the session is in progress.',{qr:'liveLeaderboardShareQr',link:'liveLeaderboardShareLink',copy:'liveLeaderboardShareCopyBtn',status:'liveLeaderboardShareCopyStatus',close:'liveLeaderboardShareCloseBtn'},false)}
function resetFromFinalRankings(){openSheet('<div class="sheet-title">Reset everything?</div><p class="hint">This will clear all players, games, and results. This cannot be undone. Are you sure?</p><div class="confirm-actions"><button type="button" class="btn modal-cancel" id="finalResetCancel">Cancel</button><button type="button" class="btn modal-confirm" id="finalResetConfirm">Reset everything</button></div>');$('finalResetCancel')?.addEventListener('click',()=>{closeSheet();finalRankingsShown=false;showFinalRankings()},{once:true});$('finalResetConfirm')?.addEventListener('click',performResetEverything,{once:true})}
